export function propertyForBuilding(id){let hash=0;for(const c of String(id))hash=(Math.imul(hash,31)+c.charCodeAt(0))>>>0;const p=layouts[hash%layouts.length],variation=(hash%9)*25;return {id:String(id),name:`Rincon residence ${String(hash%900+100)}`, ...p,rent:p.rent+variation,price:p.price+variation*400,hoa:650+hash%9*50,disclosure:NEIGHBORHOOD.disclosure};}
